// ISO 4217 says IQD = 3 and HUF = 2; Intl's CLDR-derived display digits differ

// the bug: hardcoding *100 assumes digits is always 2
function toMinorUnitsBuggy(amount) { return Math.round(amount * 100); }
console.log("JPY 1000 buggy minor units:", toMinorUnitsBuggy(1000), "(should be 1000, no sub-unit)");
console.log("BHD 1.5 buggy minor units:", toMinorUnitsBuggy(1.5), "(should be 1500 fils, not 150)");

# Python's stdlib has no currency-aware formatter, so the correct exponents are
# looked up from a small table taken from the ISO 4217 minor-unit list.
minor_unit_digits = {"USD": 2, "JPY": 0, "KRW": 0, "BHD": 3, "KWD": 3, "CLF": 4}

def to_minor_units_buggy(amount):
    return round(amount * 100)

def to_minor_units_correct(amount, currency):
    return round(amount * (10 ** minor_unit_digits[currency]))

print("JPY 1000 buggy:", to_minor_units_buggy(1000), "correct:", to_minor_units_correct(1000, "JPY"))
print("BHD 1.5 buggy:", to_minor_units_buggy(1.5), "correct:", to_minor_units_correct(1.5, "BHD"))
